namespace sv_04b97d6a80e040b4ad90ec9798c91996.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@page "/catalog"
@using sv_04b97d6a80e040b4ad90ec9798c91996.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1 class="mb-4">Product Catalog</h1>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="RetryAsync">Retry</button>
    </div>
}
else
{
    <div class="row">
        @* Left Sidebar — Filters *@
        <div class="col-md-3">
            <div class="card">
                <div class="card-header fw-bold">Filters</div>
                <div class="card-body">
                    @if (_categories is not null)
                    {
                        <h6>Category</h6>
                        <div class="mb-3">
                            @foreach (var category in _categories)
                            {
                                <div class="form-check">
                                    <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                                           checked="@_selectedCategories.Contains(category)"
                                           @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                                    <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                                </div>
                            }
                        </div>
                    }

                    <h6>Price Range</h6>
                    <div class="mb-3">
                        <div class="row g-2">
                            <div class="col-6">
                                <input type="number" class="form-control form-control-sm" placeholder="Min"
                                       @bind="_minPrice" @bind:event="oninput" min="0" step="0.01" />
                            </div>
                            <div class="col-6">
                                <input type="number" class="form-control form-control-sm" placeholder="Max"
                                       @bind="_maxPrice" @bind:event="oninput" min="0" step="0.01" />
                            </div>
                        </div>
                    </div>

                    <div class="form-check mb-3">
                        <input class="form-check-input" type="checkbox" id="inStockOnly"
                               @bind="_inStockOnly" />
                        <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                    </div>

                    <div class="d-grid gap-2">
                        <button class="btn btn-primary btn-sm" @onclick="ApplyFiltersAsync" disabled="@_loading">
                            Apply Filters
                        </button>
                        <button class="btn btn-outline-secondary btn-sm" @onclick="ClearFiltersAsync" disabled="@_loading">
                            Clear Filters
                        </button>
                    </div>
                </div>
            </div>
        </div>

        @* Main Content — Products *@
        <div class="col-md-9">
            @* Toolbar *@
            <div class="d-flex justify-content-between align-items-center mb-3">
                <div>
                    <label class="me-2 fw-semibold" for="sortBy">Sort by:</label>
                    <select id="sortBy" class="form-select form-select-sm d-inline-block w-auto"
                            @onchange="OnSortChangedAsync">
                        @foreach (var option in _sortOptions)
                        {
                            <option value="@option.Value" selected="@(option.Value == _sortBy)">@option.Label</option>
                        }
                    </select>
                </div>
                <div class="text-muted">
                    @if (_result is not null && _result.TotalCount > 0)
                    {
                        var start = (_result.Page - 1) * _result.PageSize + 1;
                        var end = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
                        <span>Showing @start–@end of @_result.TotalCount products</span>
                    }
                </div>
            </div>

            @if (_loading)
            {
                <div class="text-center py-5">
                    <div class="spinner-border text-primary" role="status">
                        <span class="visually-hidden">Loading...</span>
                    </div>
                    <p class="mt-2 text-muted">Loading products…</p>
                </div>
            }
            else if (_result is null || _result.Items.Count == 0)
            {
                <div class="text-center py-5">
                    <h5 class="text-muted">No products found</h5>
                    <p class="text-muted">Try adjusting your filters.</p>
                </div>
            }
            else
            {
                @* Product Grid *@
                <div class="row row-cols-1 row-cols-sm-2 row-cols-lg-3 g-3">
                    @foreach (var product in _result.Items)
                    {
                        <div class="col">
                            <div class="card h-100 product-card" @onclick="() => OnProductSelected.InvokeAsync(product.Id)" style="cursor: pointer;">
                                <div class="card-img-top bg-light d-flex align-items-center justify-content-center"
                                     style="height: 180px;" role="img" aria-label="@product.Name">
                                    <span class="text-muted">@product.Name</span>
                                </div>
                                <div class="card-body d-flex flex-column">
                                    <h6 class="card-title">@product.Name</h6>
                                    <p class="card-text fw-bold text-primary mb-1">@product.Price.ToString("C")</p>
                                    <p class="card-text mb-2">@RenderStars(product.Rating)</p>
                                    @if (!product.InStock)
                                    {
                                        <span class="badge bg-danger mb-2">Out of Stock</span>
                                    }
                                    <div class="mt-auto">
                                        <button class="btn btn-sm btn-success w-100"
                                                disabled="@(!product.InStock)"
                                                @onclick="() => { }" @onclick:stopPropagation="true">
                                            Add to Cart
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>
                    }
                </div>

                @* Pagination *@
                @{
                    var totalPages = (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);
                }
                @if (totalPages > 1)
                {
                    <nav class="mt-4" aria-label="Product pagination">
                        <ul class="pagination justify-content-center">
                            <li class="page-item @(_currentPage <= 1 ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(_currentPage - 1)"
                                        disabled="@(_currentPage <= 1)">Previous</button>
                            </li>
                            @for (var i = 1; i <= totalPages; i++)
                            {
                                var pageNum = i;
                                <li class="page-item @(pageNum == _currentPage ? "active" : "")">
                                    <button class="page-link" @onclick="() => GoToPageAsync(pageNum)">@pageNum</button>
                                </li>
                            }
                            <li class="page-item @(_currentPage >= totalPages ? "disabled" : "")">
                                <button class="page-link" @onclick="() => GoToPageAsync(_currentPage + 1)"
                                        disabled="@(_currentPage >= totalPages)">Next</button>
                            </li>
                        </ul>
                    </nav>
                }
            }
        </div>
    </div>
}

@code {
    [Parameter]
    public EventCallback<int> OnProductSelected { get; set; }

    private const int PageSize = 9;

    private readonly record struct SortOption(string Label, string Value);
    private static readonly SortOption[] _sortOptions =
    [
        new("Price: Low to High", "price_asc"),
        new("Price: High to Low", "price_desc"),
        new("Name: A-Z", "name_asc"),
        new("Rating: Highest", "rating_desc"),
    ];

    private List<string>? _categories;
    private HashSet<string> _selectedCategories = new();
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;
    private string _sortBy = "price_asc";
    private int _currentPage = 1;

    private PagedResult<Product>? _result;
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        await LoadInitialDataAsync();
    }

    private async Task LoadInitialDataAsync()
    {
        try
        {
            _loading = true;
            _error = null;

            var categoriesTask = ProductService.GetCategoriesAsync();
            var productsTask = SearchAsync();

            _categories = await categoriesTask;
            _result = await productsTask;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task<PagedResult<Product>> SearchAsync()
    {
        var filter = new ProductFilter(
            _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
            _minPrice,
            _maxPrice,
            _inStockOnly
        );

        return await ProductService.SearchAsync(filter, _sortBy, _currentPage, PageSize);
    }

    private async Task ApplyFiltersAsync()
    {
        _currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task ClearFiltersAsync()
    {
        _selectedCategories.Clear();
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        _currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task OnSortChangedAsync(ChangeEventArgs e)
    {
        _sortBy = e.Value?.ToString() ?? "price_asc";
        _currentPage = 1;
        await LoadProductsAsync();
    }

    private async Task GoToPageAsync(int page)
    {
        _currentPage = page;
        await LoadProductsAsync();
    }

    private async Task LoadProductsAsync()
    {
        try
        {
            _loading = true;
            _error = null;
            _result = await SearchAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task RetryAsync() => await LoadInitialDataAsync();

    private void ToggleCategory(string category, bool isChecked)
    {
        if (isChecked)
            _selectedCategories.Add(category);
        else
            _selectedCategories.Remove(category);
    }

    private static string RenderStars(double rating)
    {
        var fullStars = (int)Math.Round(rating);
        var emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

